package org.jfree.data.xy;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.List;
import org.jfree.chart.util.ObjectUtilities;
import org.jfree.data.general.Series;
import org.jfree.data.general.SeriesChangeEvent;
import org.jfree.data.general.SeriesException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class XYSeries_addOrUpdate_TriageGen2Test {

    @Test(expected = IllegalArgumentException.class)
    public void testAddOrUpdate_NullX_ThrowsException() {
        XYSeries series = new XYSeries("Test");
        series.addOrUpdate(null, 1.0);
    }

    @Test
    public void testAddOrUpdate_AllowDuplicatesTrue() {
        // When allowDuplicateXValues is true, it calls add(x, y) and returns null
        XYSeries series = new XYSeries("Test", false, true);
        XYDataItem result = series.addOrUpdate(1.0, 10.0);

        assertNull("Should return null when duplicates are allowed", result);
        assertEquals(1, series.getItemCount());
        assertEquals(1.0, series.getX(0).doubleValue(), 1e-9);
        assertEquals(10.0, series.getY(0).doubleValue(), 1e-9);

        // Add duplicate X
        series.addOrUpdate(1.0, 20.0);
        assertEquals(2, series.getItemCount());
    }

    @Test
    public void testAddOrUpdate_NoDuplicates_AddNew_NoAutoSort() {
        // autoSort = false, allowDuplicateXValues = false
        XYSeries series = new XYSeries("Test", false, false);

        XYDataItem result = series.addOrUpdate(1.0, 10.0);

        assertNull("Should return null when adding new item", result);
        assertEquals(1, series.getItemCount());
        assertEquals(1.0, series.getX(0).doubleValue(), 1e-9);
        assertEquals(10.0, series.getY(0).doubleValue(), 1e-9);
    }

    @Test
    public void testAddOrUpdate_NoDuplicates_AddNew_WithAutoSort() {
        // autoSort = true, allowDuplicateXValues = false
        XYSeries series = new XYSeries("Test", true, false);

        // Add items out of order to trigger binary search insertion logic
        series.addOrUpdate(10.0, 100.0);
        XYDataItem result = series.addOrUpdate(5.0, 50.0); // index will be negative

        assertNull(result);
        assertEquals(2, series.getItemCount());
        // Check if sorted: 5.0 should be at index 0
        assertEquals(5.0, series.getX(0).doubleValue(), 1e-9);
        assertEquals(10.0, series.getX(1).doubleValue(), 1e-9);
    }

    @Test
    public void testAddOrUpdate_NoDuplicates_UpdateExisting() {
        // autoSort = true, allowDuplicateXValues = false
        XYSeries series = new XYSeries("Test", true, false);
        series.addOrUpdate(1.0, 10.0);

        // Update existing X
        XYDataItem overwritten = series.addOrUpdate(1.0, 20.0);

        assertNotNull("Should return the overwritten item", overwritten);
        assertEquals(1.0, overwritten.getX().doubleValue(), 1e-9);
        assertEquals(10.0, overwritten.getY().doubleValue(), 1e-9);

        assertEquals(1, series.getItemCount());
        assertEquals(20.0, series.getY(0).doubleValue(), 1e-9);
    }

    @Test
    public void testAddOrUpdate_ExceedMaximumItemCount() {
        // Set maximum item count to 2
        XYSeries series = new XYSeries("Test", false, false);
        series.setMaximumItemCount(2);

        series.addOrUpdate(1.0, 10.0);
        series.addOrUpdate(2.0, 20.0);
        // This should trigger removal of index 0
        series.addOrUpdate(3.0, 30.0);

        assertEquals(2, series.getItemCount());
        // The first item (1.0) should have been removed
        assertEquals(2.0, series.getX(0).doubleValue(), 1e-9);
        assertEquals(3.0, series.getX(1).doubleValue(), 1e-9);
    }
}
